document.head.insertAdjacentHTML('beforeend','<link rel="stylesheet" href="kpi-v2.css">');
const $=s=>document.querySelector(s),money=v=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0}).format(v||0),pct=v=>new Intl.NumberFormat('pt-BR',{style:'percent',maximumFractionDigits:2}).format(v||0),sum=(r,k)=>r.reduce((s,x)=>s+(+x[k]||0),0),vr=(a,b)=>b?a/b-1:null;
const domains={Meli:'mercadolivre.com.br',Shopee:'shopee.com.br',Amazon:'amazon.com.br',MagaLu:'magazineluiza.com.br',TikTok:'tiktok.com',Via:'casasbahia.com.br',WCO:'webcontinental.com.br',Madeira:'madeiramadeira.com.br',Kabum:'kabum.com.br',Carrefour:'carrefour.com.br',Leroy:'leroymerlin.com.br',Martins:'martinsatacado.com.br'},icon=n=>`https://www.google.com/s2/favicons?domain=${domains[n]||'oficialwebshop.com.br'}&sz=64`;
const metric=(name,r,d)=>{let g=sum(r,'gmv'),p=sum(r,'produto'),l=sum(r,'liquido'),c=sum(r,'custo'),o=sum(r,'pedidos');return{name,g,p,cm2:p?l/p:0,ir:c?l/c:0,proj:g/Math.max(d,1)*30}},group=(r,k)=>Object.values(r.reduce((a,x)=>{let n=x[k]||'Outros';a[n]??={name:n,gmv:0,produto:0,custo:0,liquido:0,pedidos:0};['gmv','produto','custo','liquido','pedidos'].forEach(y=>a[n][y]+=+x[y]||0);return a},{}));
const delta=(l,v)=>`<div class="kpi-delta ${v==null?'flat':v>=0?'up':'down'}"><span>${l}</span><b>${v==null?'—':`${v>=0?'▲':'▼'} ${Math.abs(v*100).toFixed(1)}%`}</b></div>`,spark=v=>{if(!v.length)return'';let M=Math.max(...v,1),m=Math.min(...v),p=v.map((x,i)=>`${i/Math.max(v.length-1,1)*100},${30-(x-m)/(M-m||1)*26}`).join(' ');return `<svg class="sparkline" viewBox="0 0 100 32" preserveAspectRatio="none"><polyline points="${p}" fill="none" stroke="#ff6410" stroke-width="2" vector-effect="non-scaling-stroke"/><polyline points="0,32 ${p} 100,32" fill="#ff5a0016"/></svg>`};
const card=(m,t,s)=>`<article class="card kpi-card"><div class="card-head">${m.name}</div><div class="card-body"><div class="kpi-top"><div><div class="main">${money(m.g)}</div><div class="sub">VALOR PRODUTO<b>${money(m.p)}</b></div></div>${spark(s)}</div><div class="kpi-ratios"><span>CM2<b>${pct(m.cm2)}</b></span><span>IR<b>${pct(m.ir)}</b></span><span>PROJ.<b>${money(m.proj)}</b></span></div><div class="kpi-comparisons">${delta('DoD',t.dod)}${delta('MoM',t.mom)}${delta('YoY',t.yoy)}</div></div></article>`;
function bars(e,a){let M=Math.max(...a.map(x=>x.v),1);e.innerHTML=a.map(x=>`<div class="bw"><div class="bar" style="height:${x.v/M*88}%">${Math.round(x.v)}%</div><label>${x.n}</label></div>`).join('')}
function render(d){let r=d.rows,c=d.comparisons,h=d.trends,cut=new Date(d.cutoff+'T12:00:00'),days=cut.getDate(),F={GMV:()=>true,OFICIAL:x=>x.empresa.toLowerCase().includes('oficial'),PRIORIZA:x=>x.empresa.toLowerCase().includes('prioriza'),MARKETPLACE:x=>!['VD','Site'].includes(x.canal),VD:x=>x.canal==='VD',SITE:x=>x.canal==='Site'},calc=f=>{let a=c.filter(f),s=k=>sum(a,k);return{dod:vr(s('dodAtual'),s('dodAnterior')),mom:vr(s('momAtual'),s('momAnterior')),yoy:vr(s('momAtual'),s('yoyAnterior'))}},series=f=>{let a={};h.filter(f).forEach(x=>a[x.mes]=(a[x.mes]||0)+x.gmv);return Object.keys(a).sort().map(k=>a[k])},ms=Object.entries(F).map(([n,f])=>metric(n,r.filter(f),days));$('#cards').innerHTML=ms.map(m=>card(m,calc(F[m.name]),series(F[m.name]))).join('');let[all,official,prioriza,market,vd,site]=ms;$('#cutoff').textContent=cut.toLocaleDateString('pt-BR');$('#updated').textContent=new Date(d.updatedAt).toLocaleString('pt-BR',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'});$('#financial').innerHTML=[['CM2',money(all.p*all.cm2)],['FRETE',money(sum(r,'saldoFrete'))],['TICKET MÉDIO',money(all.g/sum(r,'pedidos'))],['PROVISIONAMENTOS','A integrar DAX']].map(x=>`<div class="fin"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('');let ch=group(r,'canal').sort((a,b)=>b.gmv-a.gmv),max=ch[0]?.gmv||1,cell=v=>`<span class="delta ${v==null?'flat':v>=0?'up':'down'}">${v==null?'—':`${v>=0?'▲':'▼'} ${Math.abs(v*100).toFixed(1)}%`}</span>`;$('thead tr').innerHTML='<th>Canal</th><th>GMV</th><th>Share</th><th>CM2</th><th>IR</th><th>DoD</th><th>MoM</th><th>YoY</th>';$('#channelRows').innerHTML=ch.slice(0,14).map((x,i)=>{let f=y=>y.canal===x.name,t=calc(f),det=r.filter(f);return `<tr class="channel-main" data-drill="d${i}"><td><span class="chev">›</span><img class="logo" src="${icon(x.name)}">${x.name}</td><td><strong>${money(x.gmv)}</strong></td><td>${pct(x.gmv/all.g)}</td><td>${pct(x.produto?x.liquido/x.produto:0)}</td><td>${pct(x.custo?x.liquido/x.custo:0)}</td><td>${cell(t.dod)}</td><td>${cell(t.mom)}</td><td>${cell(t.yoy)}</td></tr><tr id="d${i}" class="drill-row"><td colspan="8" class="drill-content"><div class="drill-grid">${det.map(z=>`<div class="drill-item"><b>${z.empresa} • ${z.subcanal||z.canal}</b><span>${money(z.gmv)} • ${z.pedidos} pedidos</span></div>`).join('')}</div></td></tr>`}).join('');document.querySelectorAll('.channel-main').forEach(x=>x.onclick=()=>{$('#'+x.dataset.drill).classList.toggle('open')});$('#mixRows').innerHTML=r.sort((a,b)=>b.gmv-a.gmv).slice(0,12).map(x=>`<div class="mix-row"><span>${x.empresa} • ${x.subcanal||x.canal}</span><div class="track"><i style="width:${x.gmv/max*100}%"></i></div><b>${money(x.gmv)}</b></div>`).join('');bars($('#buChart'),[{n:'Marketplace',v:market.g/all.g*100},{n:'VD',v:vd.g/all.g*100},{n:'Site',v:site.g/all.g*100}]);bars($('#modalChart'),[{n:'Oficial',v:official.g/all.g*100},{n:'Prioriza',v:prioriza.g/all.g*100}]);$('#loading').classList.add('hide')}
fetch('/api/data',{cache:'no-store'}).then(x=>x.json()).then(render).catch(e=>$('#loading').textContent='ERRO • '+e.message);
